def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    bg = max(counts.items(), key=lambda x: x[1])[0]

    non_bg = [(c, counts[c]) for c in counts if c != bg]
    non_bg.sort(key=lambda x: x[1], reverse=True)

    if len(non_bg) == 0:
        return [[bg] * w for _ in range(h)]

    # If only one non-bg color, it both stays and uses its own pattern
    if len(non_bg) == 1:
        return grid  # Return as-is

    main_color = non_bg[0][0]  # More common - stays
    marker_color = non_bg[1][0]  # Less common - creates copies

    main_positions = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == main_color}
    marker_positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker_color]

    result = [[bg] * w for _ in range(h)]

    # Place main shape
    for r, c in main_positions:
        result[r][c] = main_color

    # For each marker position, place main pattern at that location
    if main_positions:
        rows_main = sorted([r for r, c in main_positions])
        cols_main = sorted([c for r, c in main_positions])
        min_r, max_r = rows_main[0], rows_main[-1]
        min_c, max_c = cols_main[0], cols_main[-1]

        main_rel = {(r - min_r, c - min_c) for r, c in main_positions}

        for mi, mj in marker_positions:
            for dr, dc in main_rel:
                nr, nc = mi + dr, mj + dc
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = marker_color

    return result
